-- =============================================================================
-- SDA / tenant: injetar {duration:} nos ChordPros a partir de songs.duration
-- Dump analisado: db/songs.json + db/chordpros.json (2026-09-11)
--
-- ONDE RODAR: banco TENANT (não o landlord). Tabela `chordpros`.
-- O QUE FAZ: só escreve/alinha a diretiva {duration: MM:SS}. Não mexe em letra,
--            acordes, {tempo:}, {key:} nem em cifras soft-deleted.
-- TRAVA: cada UPDATE exige o updated_at do dump. Se a cifra mudou na produção
--        desde o export, a linha afeta 0 rows (não sobrescreve trabalho novo).
--
-- PARTE 1 — 118 INSERTs (recomendado): cifras sem {duration:} cujo song.duration
--           passa no gate do Titan (≥ 20 s, m:ss).
-- PARTE 2a — 11 REPLACEs |Δ|<30s: cifra já tinha duração, quase igual ao song
--            (arredondamento / vídeo).
-- PARTE 2b — 10 REPLACEs |Δ|≥30s: COMENTADOS. Song e cifra discordam de verdade
--            (arranjo vs YouTube?). Revisar um a um antes de descomentar.
--
-- Conferir depois:
--   SELECT id FROM chordpros WHERE deleted_at IS NULL
--     AND chordpro NOT LIKE '%{duration:%'
--     AND chordpro NOT LIKE '%{duration :%';
-- =============================================================================

SET NAMES utf8mb4;
SET @old_sql_safe_updates := @@SQL_SAFE_UPDATES;
SET SQL_SAFE_UPDATES = 0;

START TRANSACTION;

-- -----------------------------------------------------------------------------
-- PARTE 1: inserir {duration:} onde falta
-- -----------------------------------------------------------------------------

