-- ids parte 2b COMENTADOS (10): 3, 8, 10, 11, 55, 96, 101, 102, 109, 115

-- Verificação imediata (cifras vivas ainda sem diretiva duration):
SELECT c.id, c.song_id, c.name,
       s.title, s.duration AS song_duration
FROM chordpros c
LEFT JOIN songs s ON s.id = c.song_id
WHERE c.deleted_at IS NULL
  AND c.chordpro NOT LIKE '%{duration:%'
  AND c.chordpro NOT LIKE '%{duration :%'
ORDER BY c.id;

